-- =====================================================================
-- ZYRA — 0014_viabilidad_cuestionario_definitivo.sql
-- Publica el CUESTIONARIO FUNCIONAL DEFINITIVO de Viabilidad como
-- plantillas GLOBALES (servicio_id = null) y archiva las provisionales
-- de cada servicio, conservando su historial.
--
-- Fuente: docs/ZYRA_Cuestionario_Viabilidad_Definitivo.txt (no modificado).
-- Contenido generado: 118 preguntas (97 previabilidad + 21 ingenieria) y
-- 58 reglas multicriterio, con unidad/evidencia/activacion exactas.
--
-- Idempotente: si ya existe una plantilla global activa para la etapa en
-- la empresa, no se vuelve a sembrar.
-- =====================================================================
begin;

-- ═════════════════════════════════════════════════════════════════════
-- Sembrador idempotente del cuestionario definitivo.
--   - Crea plantillas globales activas por etapa (servicio_id null).
--   - Archiva las plantillas activas especificas de servicio de esa etapa.
--   - Carga secciones, preguntas, opciones, condiciones de activacion y reglas.
-- No otorga EXECUTE a roles de aplicacion: es una herranienta de seed/migracion.
-- ═════════════════════════════════════════════════════════════════════
create or replace function public.sembrar_cuestionario_viabilidad_definitivo(
  p_empresa_nombre text default 'ESSE Solar'
) returns jsonb language plpgsql security definer set search_path = public as $$
declare
  v_payload constant jsonb := $json$[{"etapa":"previabilidad","nombre":"inspeccion_previabilidad_sitio","secciones":[{"codigo":"entorno_acceso_logistica","titulo":"entorno_acceso_logistica","preguntas":[{"codigo":"acceso_vehiculo","texto":"¿Cómo es el acceso del vehículo de trabajo hasta el sitio de instalación?","ayuda":"Evalúa la vía por la que llegarían el personal, paneles, herramientas y materiales. Considera calles, terracería, callejones, portones, radios de giro y cualquier imposibilidad evidente de acceso.","tipo":"opcion_unica","obligatoria":true,"unidad":null,"evidencia_tipo":"foto","evidencia_obligatoria":true,"evidencia_instruccion":"Fotografiar el acceso principal y el trayecto disponible para el vehículo de trabajo.","opciones":[{"valor":"pavimentado","etiqueta":"pavimentado"},{"valor":"terraceria","etiqueta":"terraceria"},{"valor":"callejon_estrecho","etiqueta":"callejon_estrecho"},{"valor":"sin_acceso","etiqueta":"sin_acceso"}]},{"codigo":"ancho_callejon_ok","texto":"¿El ancho disponible en el callejón permite el paso de una camioneta de trabajo?","ayuda":"Considera el ancho del vehículo y un espacio razonable para maniobrar sin golpear muros, postes, vehículos u otros obstáculos.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"acceso_vehiculo","operador":"=","valor":"callejon_estrecho"}]},{"codigo":"obstaculos_aereos","texto":"¿Existen cables, ramas, estructuras u otros obstáculos aéreos que puedan impedir o dificultar el paso?","ayuda":"Registra obstáculos visibles que interfieran con el acceso por el callejón.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"foto","evidencia_obligatoria":false,"evidencia_obligatoria_condicion":{"pregunta":"obstaculos_aereos","operador":"=","valor":"true"},"evidencia_instruccion":"Si existen obstáculos, fotografiarlos mostrando su relación con el paso disponible.","activacion":[{"pregunta":"acceso_vehiculo","operador":"=","valor":"callejon_estrecho"}]},{"codigo":"espacio_descarga","texto":"¿Existe una zona segura donde estacionar y descargar paneles, herramientas y materiales?","ayuda":"Evalúa si la descarga puede realizarse sin generar una maniobra impracticable o insegura.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"foto","evidencia_obligatoria":true,"evidencia_instruccion":"Fotografiar la zona prevista para estacionamiento y descarga."},{"codigo":"suelo_descarga","texto":"¿Cómo es el suelo de la zona donde se realizará la descarga?","ayuda":"Clasifica la superficie donde se estacionaría el vehículo y se manipularían los materiales.","tipo":"opcion_unica","obligatoria":true,"unidad":null,"evidencia_tipo":"foto","evidencia_obligatoria":true,"evidencia_instruccion":"Fotografiar la superficie de la zona de descarga.","opciones":[{"valor":"firme","etiqueta":"firme"},{"valor":"blando","etiqueta":"blando"}],"activacion":[{"pregunta":"espacio_descarga","operador":"=","valor":"true"}]},{"codigo":"metodo_elevacion","texto":"¿Qué método se utilizaría para subir los paneles y materiales hasta el techo?","ayuda":"Selecciona el método preliminar viable según las condiciones observables del sitio.","tipo":"opcion_unica","obligatoria":true,"unidad":null,"evidencia_tipo":"foto","evidencia_obligatoria":true,"evidencia_instruccion":"Fotografiar la zona donde se realizaría la maniobra de elevación.","opciones":[{"valor":"escalera","etiqueta":"escalera"},{"valor":"andamio","etiqueta":"andamio"},{"valor":"grua","etiqueta":"grua"},{"valor":"elevador","etiqueta":"elevador"}]},{"codigo":"escalera_altura_ok","texto":"¿La escalera disponible alcanza de forma adecuada la altura necesaria para acceder al techo?","ayuda":"Comprueba visualmente que la altura sea suficiente para el acceso previsto.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"metodo_elevacion","operador":"=","valor":"escalera"}]},{"codigo":"escalera_ancho_ok","texto":"¿El espacio de acceso mediante escalera permite subir un panel sin obstrucciones importantes?","ayuda":"Considera el ancho del panel y el espacio real disponible para la maniobra.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"metodo_elevacion","operador":"=","valor":"escalera"}]},{"codigo":"escalera_buen_estado","texto":"¿La escalera que se utilizaría se encuentra en buen estado físico?","ayuda":"Revisa que no presente daños evidentes incompatibles con su uso previsto.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"foto","evidencia_obligatoria":true,"evidencia_instruccion":"Fotografiar la escalera completa y cualquier deterioro visible.","activacion":[{"pregunta":"metodo_elevacion","operador":"=","valor":"escalera"}]},{"codigo":"grua_espacio_ok","texto":"¿Existe espacio suficiente para posicionar y operar una grúa?","ayuda":"Evalúa si la grúa podría colocarse y maniobrar en el sitio previsto.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"metodo_elevacion","operador":"=","valor":"grua"}]},{"codigo":"grua_lineas_tension","texto":"¿Existen líneas de alta tensión u otros elementos aéreos que interfieran con la operación de la grúa?","ayuda":"Identifica interferencias visibles próximas al área de maniobra.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"foto","evidencia_obligatoria":false,"evidencia_obligatoria_condicion":{"pregunta":"grua_lineas_tension","operador":"=","valor":"true"},"evidencia_instruccion":"Fotografiar las líneas u obstáculos mostrando su relación con la zona de operación.","activacion":[{"pregunta":"metodo_elevacion","operador":"=","valor":"grua"}]},{"codigo":"grua_permiso_municipal","texto":"¿Se requiere permiso municipal para operar la grúa en este sitio?","ayuda":"Registra si la maniobra está sujeta a una autorización municipal conocida.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"metodo_elevacion","operador":"=","valor":"grua"}]},{"codigo":"riesgos_entorno","texto":"¿Qué riesgos u obstáculos están presentes alrededor del área de trabajo? Selecciona todos los que correspondan.","ayuda":"Esta pregunta registra la existencia del riesgo. Las preguntas hijas solicitan únicamente el detalle accionable y no vuelven a preguntar si el riesgo existe.","tipo":"opcion_multiple","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"opciones":[{"valor":"perros","etiqueta":"perros"},{"valor":"lineas_tension","etiqueta":"lineas_tension"},{"valor":"riesgo_social","etiqueta":"riesgo_social"},{"valor":"arboles","etiqueta":"arboles"}]},{"codigo":"perros_cliente_asegura","texto":"¿El cliente puede mantener asegurados o alejados de la zona de trabajo a los perros durante los trabajos?","ayuda":"La existencia de perros ya fue indicada en riesgos_entorno. Aquí únicamente se registra si pueden mantenerse controlados.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"riesgos_entorno","operador":"contiene","valor":"perros"}]},{"codigo":"lineas_tension_distancia","texto":"Describe la ubicación y distancia aproximada de las líneas de tensión respecto al área de trabajo.","ayuda":"Describe únicamente lo observable. Esta información no sustituye una evaluación eléctrica o de CFE.","tipo":"texto","obligatoria":true,"unidad":null,"evidencia_tipo":"foto","evidencia_obligatoria":true,"evidencia_instruccion":"Fotografiar las líneas mostrando su posición relativa respecto al área de trabajo.","activacion":[{"pregunta":"riesgos_entorno","operador":"contiene","valor":"lineas_tension"}]},{"codigo":"riesgo_social_medidas","texto":"Describe las medidas de seguridad o coordinación previstas debido al riesgo social identificado.","ayuda":"Registra medidas operativas previstas para proteger al personal y los materiales.","tipo":"texto","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"riesgos_entorno","operador":"contiene","valor":"riesgo_social"}]},{"codigo":"arboles_cantidad","texto":"Indica cuántos árboles interfieren y dónde están ubicados respecto al área propuesta de instalación.","ayuda":"Describe cantidad, ubicación y forma de interferencia observable.","tipo":"texto","obligatoria":true,"unidad":null,"evidencia_tipo":"foto","evidencia_obligatoria":true,"evidencia_instruccion":"Fotografiar los árboles mostrando su relación con el área propuesta de instalación.","activacion":[{"pregunta":"riesgos_entorno","operador":"contiene","valor":"arboles"}]}]},{"codigo":"estructura_condiciones_techo","titulo":"estructura_condiciones_techo","preguntas":[{"codigo":"material_techo","texto":"¿Cuál es el material principal de la cubierta donde se pretende instalar el sistema fotovoltaico?","ayuda":"Selecciona el material predominante del área propuesta. Esta respuesta determina qué preguntas específicas se muestran.","tipo":"opcion_unica","obligatoria":true,"unidad":null,"evidencia_tipo":"foto","evidencia_obligatoria":true,"evidencia_instruccion":"Fotografiar una vista general de la cubierta y del área propuesta para instalación.","opciones":[{"valor":"losa_concreto","etiqueta":"losa_concreto"},{"valor":"lamina_galvanizada","etiqueta":"lamina_galvanizada"},{"valor":"teja","etiqueta":"teja"},{"valor":"panel_sandwich","etiqueta":"panel_sandwich"},{"valor":"asbesto","etiqueta":"asbesto"}]},{"codigo":"losa_impermeabilizacion","texto":"¿La losa cuenta actualmente con impermeabilización?","ayuda":"Registra la existencia observable o informada de impermeabilización en el área propuesta.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"material_techo","operador":"=","valor":"losa_concreto"}]},{"codigo":"losa_anclaje_sin_romper","texto":"¿Se puede realizar el anclaje previsto sin comprometer la impermeabilización existente?","ayuda":"Registra únicamente la viabilidad preliminar observable. La solución final de montaje corresponde a Ingeniería.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"material_techo","operador":"=","valor":"losa_concreto"}]},{"codigo":"losa_espesor","texto":"Registra el espesor observado o medido de la losa.","ayuda":"Captura el valor disponible sin convertirlo por sí solo en un criterio universal de aceptación.","tipo":"numero","obligatoria":true,"unidad":"cm","evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"material_techo","operador":"=","valor":"losa_concreto"}]},{"codigo":"lamina_calibre","texto":"¿Qué calibre de lámina está reportado o identificado?","ayuda":"Registra el calibre como dato de la cubierta. No debe utilizarse por sí solo como criterio universal automático.","tipo":"opcion_unica","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"opciones":[{"valor":"calibre_22","etiqueta":"calibre_22"},{"valor":"calibre_24","etiqueta":"calibre_24"},{"valor":"calibre_26","etiqueta":"calibre_26"},{"valor":"calibre_30","etiqueta":"calibre_30"},{"valor":"otro","etiqueta":"otro"}],"activacion":[{"pregunta":"material_techo","operador":"=","valor":"lamina_galvanizada"}]},{"codigo":"lamina_espesor_mm","texto":"Si puede medirse, registra el espesor real de la lámina.","ayuda":"Conserva esta medición como dato técnico. No usar 0.7 mm ni ningún otro umbral universal sin aprobación técnica explícita.","tipo":"numero","obligatoria":false,"unidad":"mm","evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"material_techo","operador":"=","valor":"lamina_galvanizada"}]},{"codigo":"lamina_soporte","texto":"¿Sobre qué tipo de elemento está fijada principalmente la lámina?","ayuda":"Selecciona el soporte observable predominante.","tipo":"opcion_unica","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"opciones":[{"valor":"polin","etiqueta":"polin"},{"valor":"madera","etiqueta":"madera"}],"activacion":[{"pregunta":"material_techo","operador":"=","valor":"lamina_galvanizada"}]},{"codigo":"lamina_antiguedad","texto":"Según la información disponible, ¿la lámina tiene menos de 10 años de antigüedad?","ayuda":"Utiliza información proporcionada por el cliente o documentación disponible. No inventes una antigüedad si se desconoce.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"material_techo","operador":"=","valor":"lamina_galvanizada"}]},{"codigo":"lamina_oxidada","texto":"¿La lámina presenta oxidación, perforaciones o deterioro visible?","ayuda":"Revisa especialmente el área propuesta y las zonas de fijación observables.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"foto","evidencia_obligatoria":true,"evidencia_instruccion":"Fotografiar el estado general de la lámina y cualquier zona oxidada, perforada o deteriorada.","activacion":[{"pregunta":"material_techo","operador":"=","valor":"lamina_galvanizada"}]},{"codigo":"lamina_polin_estado","texto":"¿Los polines o soportes observables se encuentran en buen estado?","ayuda":"Evalúa únicamente el estado observable. Esta respuesta no equivale a un dictamen estructural.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"material_techo","operador":"=","valor":"lamina_galvanizada"}]},{"codigo":"teja_tipo","texto":"¿De qué material es principalmente la teja?","ayuda":"Selecciona el material predominante del área propuesta.","tipo":"opcion_unica","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"opciones":[{"valor":"arcilla","etiqueta":"arcilla"},{"valor":"concreto","etiqueta":"concreto"},{"valor":"plastica","etiqueta":"plastica"}],"activacion":[{"pregunta":"material_techo","operador":"=","valor":"teja"}]},{"codigo":"teja_estado","texto":"¿Las tejas del área propuesta se encuentran en buen estado, sin roturas o deterioro importante visible?","ayuda":"Revisa el estado observable del área donde se pretende trabajar.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"foto","evidencia_obligatoria":true,"evidencia_instruccion":"Fotografiar el estado general y cualquier pieza rota, desplazada o deteriorada.","activacion":[{"pregunta":"material_techo","operador":"=","valor":"teja"}]},{"codigo":"teja_ganchos_especiales","texto":"¿La cubierta permite utilizar un sistema de montaje con ganchos especiales para teja?","ayuda":"Registra únicamente viabilidad preliminar. La selección final del sistema de montaje corresponde a Ingeniería.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"material_techo","operador":"=","valor":"teja"}]},{"codigo":"teja_estructura","texto":"¿Cuál es la estructura de soporte observable bajo la teja?","ayuda":"Selecciona el material estructural observable predominante.","tipo":"opcion_unica","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"opciones":[{"valor":"madera","etiqueta":"madera"},{"valor":"metal","etiqueta":"metal"}],"activacion":[{"pregunta":"material_techo","operador":"=","valor":"teja"}]},{"codigo":"panel_espesor","texto":"Registra el espesor observado o medido del panel sándwich.","ayuda":"Captura la medición disponible sin inferir por sí sola aptitud estructural.","tipo":"numero","obligatoria":true,"unidad":"mm","evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"material_techo","operador":"=","valor":"panel_sandwich"}]},{"codigo":"panel_aislamiento","texto":"¿Qué tipo de aislamiento utiliza el panel sándwich?","ayuda":"Selecciona el material de aislamiento identificado.","tipo":"opcion_unica","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"opciones":[{"valor":"poliuretano","etiqueta":"poliuretano"},{"valor":"poliestireno","etiqueta":"poliestireno"}],"activacion":[{"pregunta":"material_techo","operador":"=","valor":"panel_sandwich"}]},{"codigo":"panel_estado","texto":"¿Los paneles del área de instalación se encuentran en buen estado físico?","ayuda":"Observa delaminación, daños, deformaciones u otros deterioros visibles.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"foto","evidencia_obligatoria":true,"evidencia_instruccion":"Fotografiar el estado general y cualquier deterioro del panel.","activacion":[{"pregunta":"material_techo","operador":"=","valor":"panel_sandwich"}]},{"codigo":"asbesto_confirmado","texto":"¿La cubierta identificada corresponde efectivamente a asbesto-cemento?","ayuda":"Confirma únicamente dentro del alcance seguro de una inspección visual o documental. No manipular, romper, perforar ni alterar el material para verificarlo.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"foto","evidencia_obligatoria":true,"evidencia_instruccion":"Fotografiar la cubierta identificada sin manipular el material.","activacion":[{"pregunta":"material_techo","operador":"=","valor":"asbesto"}]},{"codigo":"goteras","texto":"¿Se observan o reportan goteras, filtraciones o ingreso de agua a través del techo?","ayuda":"Considera tanto evidencia visible como información proporcionada por el cliente.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"foto","evidencia_obligatoria":false,"evidencia_obligatoria_condicion":{"pregunta":"goteras","operador":"=","valor":"true"},"evidencia_instruccion":"Si existe evidencia visible, fotografiar la zona afectada; si solo existe reporte del cliente, fotografiar la zona señalada cuando sea posible."},{"codigo":"gotera_area_instalacion","texto":"¿La filtración se encuentra dentro o afecta directamente el área propuesta para instalar paneles?","ayuda":"Relaciona la zona de filtración con el área prevista de instalación.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"goteras","operador":"=","valor":"true"}]},{"codigo":"gotera_activa","texto":"¿La filtración está activa actualmente o corresponde a un daño histórico?","ayuda":"Distingue entre un problema presente y una filtración reportada como histórica.","tipo":"opcion_unica","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"opciones":[{"valor":"activa","etiqueta":"activa"},{"valor":"historica","etiqueta":"historica"}],"activacion":[{"pregunta":"goteras","operador":"=","valor":"true"}]},{"codigo":"gotera_cliente_repara","texto":"¿El cliente está dispuesto a reparar la filtración antes de la instalación?","ayuda":"Registra el compromiso preliminar del cliente cuando existe una filtración.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"goteras","operador":"=","valor":"true"}]},{"codigo":"material_oxidado","texto":"¿Se observa material oxidado, corroído, quebradizo o deteriorado en la cubierta o sus soportes visibles?","ayuda":"Revisa condiciones visibles que puedan afectar el montaje o requerir evaluación adicional.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"foto","evidencia_obligatoria":false,"evidencia_obligatoria_condicion":{"pregunta":"material_oxidado","operador":"=","valor":"true"},"evidencia_instruccion":"Fotografiar las áreas deterioradas y su relación con el área propuesta de instalación."},{"codigo":"oxidacion_tipo","texto":"¿El deterioro observado parece superficial o afecta elementos estructurales?","ayuda":"Clasifica únicamente según lo observable. La condición estructural definitiva puede requerir validación especializada.","tipo":"opcion_unica","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"opciones":[{"valor":"superficial","etiqueta":"superficial"},{"valor":"estructural","etiqueta":"estructural"}],"activacion":[{"pregunta":"material_oxidado","operador":"=","valor":"true"}]},{"codigo":"oxidacion_area_anclaje","texto":"¿El deterioro coincide con zonas donde sería necesario realizar anclajes o fijaciones?","ayuda":"Relaciona visualmente el deterioro con las posibles zonas de fijación.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"material_oxidado","operador":"=","valor":"true"}]},{"codigo":"pendiente_techo","texto":"¿Cómo se clasifica la pendiente del área de techo propuesta?","ayuda":"Selecciona la categoría que mejor represente la geometría observable.","tipo":"opcion_unica","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"opciones":[{"valor":"plano","etiqueta":"plano"},{"valor":"baja","etiqueta":"baja"},{"valor":"media","etiqueta":"media"},{"valor":"alta","etiqueta":"alta"}]},{"codigo":"pendiente_estructura_e