da al proyecto.","tipo":"opcion_unica","obligatoria":true,"unidad":null,"evidencia_tipo":"documento","evidencia_obligatoria":true,"evidencia_instruccion":"Adjuntar documento, respuesta o evidencia técnica que respalde el estado registrado.","opciones":[{"valor":"si","etiqueta":"si"},{"valor":"no","etiqueta":"no"},{"valor":"se_desconoce","etiqueta":"se_desconoce"}]}]},{"codigo":"inversor","titulo":"inversor","preguntas":[{"codigo":"inversor_certificado_ul","texto":"¿El inversor cuenta con la certificación requerida indicada en la especificación (UL 1741 SB e IEEE 1547)?","ayuda":"Responder con base en la documentación técnica del equipo seleccionado.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"documento","evidencia_obligatoria":true,"evidencia_instruccion":"Adjuntar certificado o documentación técnica del inversor."},{"codigo":"inversor_certificado_vigente","texto":"¿El certificado del inversor se encuentra vigente?","ayuda":"Verifica la vigencia según la documentación aportada.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"documento","evidencia_obligatoria":true,"evidencia_instruccion":"Adjuntar evidencia documental de vigencia cuando corresponda.","activacion":[{"pregunta":"inversor_certificado_ul","operador":"=","valor":"true"}]},{"codigo":"inversor_modelo","texto":"Registra la marca y modelo del inversor seleccionado.","ayuda":"Utiliza la identificación exacta del equipo del diseño final.","tipo":"texto","obligatoria":true,"unidad":null,"evidencia_tipo":"documento","evidencia_obligatoria":true,"evidencia_instruccion":"Adjuntar ficha técnica o documento donde se identifique el modelo."},{"codigo":"inversor_eficiencia","texto":"Registra la eficiencia nominal declarada del inversor.","ayuda":"Captura el valor de la ficha técnica. No inferir ni estimar sin documentación.","tipo":"numero","obligatoria":true,"unidad":"%","evidencia_tipo":"documento","evidencia_obligatoria":true,"evidencia_instruccion":"Adjuntar ficha técnica donde aparezca la eficiencia."}]},{"codigo":"modulos","titulo":"modulos","preguntas":[{"codigo":"modulos_certificado_nmx","texto":"¿Los módulos cuentan con certificación NMX-J-618-ANCE?","ayuda":"Responder con base en certificados o documentación técnica del modelo seleccionado.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"documento","evidencia_obligatoria":true,"evidencia_instruccion":"Adjuntar certificado o documentación de los módulos."},{"codigo":"modulos_certificado_iec","texto":"Cuando NMX no aplica o está ausente, ¿los módulos cuentan con IEC 61215 o equivalente?","ayuda":"Responder con base en documentación técnica disponible.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"documento","evidencia_obligatoria":true,"evidencia_instruccion":"Adjuntar certificación IEC o equivalente cuando corresponda.","activacion":[{"pregunta":"modulos_certificado_nmx","operador":"=","valor":"false"}]}]},{"codigo":"cableado_protecciones","titulo":"cableado_protecciones","preguntas":[{"codigo":"cableado_certificado_600v","texto":"¿El cableado seleccionado cuenta con certificación para 600 V y protección UV según el diseño?","ayuda":"Verifica las características declaradas del cableado seleccionado.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"documento","evidencia_obligatoria":true,"evidencia_instruccion":"Adjuntar ficha o certificado del cableado."},{"codigo":"cableado_especifico_fv","texto":"¿El cableado seleccionado es específico para aplicaciones fotovoltaicas?","ayuda":"Responder con base en la documentación del producto.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"documento","evidencia_obligatoria":true,"evidencia_instruccion":"Adjuntar documentación técnica que identifique el uso previsto del cableado.","activacion":[{"pregunta":"cableado_certificado_600v","operador":"=","valor":"true"}]},{"codigo":"proteccion_arco","texto":"¿El diseño incorpora protección de falla por arco cuando corresponda?","ayuda":"Esta respuesta no produce rechazo automático por sí sola. La aplicabilidad debe validarse técnicamente cuando la regla correspondiente se active.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"documento","evidencia_obligatoria":true,"evidencia_instruccion":"Adjuntar parte del diseño o especificación donde se documente la protección o su tratamiento."},{"codigo":"proteccion_arco_certificada","texto":"Si el diseño incorpora protección de falla por arco, ¿el dispositivo especificado cuenta con certificación aplicable?","ayuda":"Responder con base en documentación del dispositivo seleccionado.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"documento","evidencia_obligatoria":true,"evidencia_instruccion":"Adjuntar certificado o ficha técnica del dispositivo.","activacion":[{"pregunta":"proteccion_arco","operador":"=","valor":"true"}]}]},{"codigo":"diseno_electrico_puesta_tierra","titulo":"diseno_electrico_puesta_tierra","preguntas":[{"codigo":"tension_cc_sistema","texto":"Registra la tensión máxima de corriente continua del diseño.","ayuda":"Captura el valor final calculado o documentado por Ingeniería.","tipo":"numero","obligatoria":true,"unidad":"V","evidencia_tipo":"documento","evidencia_obligatoria":true,"evidencia_instruccion":"Adjuntar memoria, cálculo o documento del diseño donde se respalde la tensión indicada."},{"codigo":"resistencia_tierra","texto":"Registra la resistencia medida o proyectada del sistema de puesta a tierra.","ayuda":"Captura el valor documentado en el diseño o medición correspondiente.","tipo":"numero","obligatoria":true,"unidad":"ohm","evidencia_tipo":"documento","evidencia_obligatoria":true,"evidencia_instruccion":"Adjuntar medición, memoria o documento que respalde el valor."},{"codigo":"mejora_tierra_posible","texto":"Si la resistencia supera el criterio aplicable, ¿puede corregirse mediante una mejora del sistema de puesta a tierra?","ayuda":"Registra la viabilidad técnica de corrección definida por Ingeniería.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null,"activacion":[{"pregunta":"resistencia_tierra","operador":"is_not_null"}]}]},{"codigo":"documentacion_ingenieria","titulo":"documentacion_ingenieria","preguntas":[{"codigo":"memoria_calculo","texto":"¿La memoria de cálculo del proyecto está completa y aprobada?","ayuda":"Confirma el estado del documento técnico final.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"documento","evidencia_obligatoria":true,"evidencia_instruccion":"Adjuntar la memoria de cálculo aprobada."},{"codigo":"diagrama_unifilar","texto":"¿El diagrama unifilar del proyecto está completo y aprobado?","ayuda":"Confirma el estado del diagrama correspondiente al diseño final.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"documento","evidencia_obligatoria":true,"evidencia_instruccion":"Adjuntar el diagrama unifilar aprobado."},{"codigo":"fichas_tecnicas","texto":"¿Se adjuntaron las fichas técnicas finales de los equipos y componentes seleccionados?","ayuda":"Confirma que el expediente contiene la documentación técnica final.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"documento","evidencia_obligatoria":true,"evidencia_instruccion":"Adjuntar las fichas técnicas finales."},{"codigo":"certificado_inversor_documento","texto":"¿Se adjuntó el certificado del inversor seleccionado?","ayuda":"Confirma la presencia del documento en el expediente.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"documento","evidencia_obligatoria":true,"evidencia_instruccion":"Adjuntar certificado del inversor."},{"codigo":"certificado_modulos_documento","texto":"¿Se adjuntaron los certificados de los módulos seleccionados?","ayuda":"Confirma la presencia de los documentos en el expediente.","tipo":"booleano","obligatoria":true,"unidad":null,"evidencia_tipo":"documento","evidencia_obligatoria":true,"evidencia_instruccion":"Adjuntar certificados de módulos."},{"codigo":"observaciones_ingenieria","texto":"Registra observaciones adicionales de Ingeniería que deban conservarse en la revisión.","ayuda":"Utiliza este campo para consideraciones técnicas no capturadas en las preguntas anteriores.","tipo":"texto","obligatoria":false,"unidad":null,"evidencia_tipo":null,"evidencia_obligatoria":false,"evidencia_instruccion":null}]}],"reglas":[{"etiqueta":"ING-R001","codigo":"regla_inversor_sin_certificacion","severidad":"bloqueante","efecto":"no_apto","cuando":{"pregunta":"inversor_certificado_ul","operador":"=","valor":"false"},"mensaje":"Inversor sin certificación requerida","accion_o_tipo":"Seleccionar inversor certificado"},{"etiqueta":"ING-R002","codigo":"regla_cableado_sin_certificacion","severidad":"bloqueante","efecto":"no_apto","cuando":{"pregunta":"cableado_certificado_600v","operador":"=","valor":"false"},"mensaje":"Cableado sin certificación requerida","accion_o_tipo":"Seleccionar cableado certificado"},{"etiqueta":"ING-R003","codigo":"regla_proteccion_arco_faltante","severidad":"requiere_especialista","efecto":"validacion_especializada","cuando":{"and":[{"pregunta":"proteccion_arco","operador":"=","valor":"false"},{"pregunta":"tension_cc_sistema","operador":">=","valor":"80"}]},"mensaje":"Falta protección de arco en condición donde puede aplicar","accion_o_tipo":"electrico"},{"etiqueta":"ING-R004","codigo":"regla_transformador_ingenieria_no","severidad":"requiere_especialista","efecto":"validacion_especializada","cuando":{"pregunta":"transformador_capacidad_confirmada","operador":"=","valor":"no"},"mensaje":"Capacidad de red no disponible","accion_o_tipo":"cfe"},{"etiqueta":"ING-R005","codigo":"regla_transformador_ingenieria_desconocido","severidad":"requiere_especialista","efecto":"validacion_especializada","cuando":{"pregunta":"transformador_capacidad_confirmada","operador":"=","valor":"se_desconoce"},"mensaje":"Capacidad de red no confirmada","accion_o_tipo":"cfe"},{"etiqueta":"ING-R006","codigo":"regla_potencia_ingenieria_limite","severidad":"requiere_especialista","efecto":"validacion_especializada","cuando":{"pregunta":"potencia_kw","operador":">=","valor":"700"},"mensaje":"Sistema fuera de generación exenta","accion_o_tipo":"legal"},{"etiqueta":"ING-R007","codigo":"regla_inversor_eficiencia_baja","severidad":"observacion","efecto":"observacion","cuando":{"pregunta":"inversor_eficiencia","operador":"<","valor":"95"},"mensaje":"Eficiencia nominal menor a 95%","accion_o_tipo":"Revisar selección; criterio sujeto a validación técnica"},{"etiqueta":"ING-R008","codigo":"regla_modulos_sin_certificacion","severidad":"observacion","efecto":"observacion","cuando":{"and":[{"pregunta":"modulos_certificado_nmx","operador":"=","valor":"false"},{"pregunta":"modulos_certificado_iec","operador":"=","valor":"false"}]},"mensaje":"Módulos sin certificación declarada","accion_o_tipo":"Seleccionar módulos certificados"},{"etiqueta":"ING-R009","codigo":"regla_tierra_inadecuada","severidad":"observacion","efecto":"observacion","cuando":{"and":[{"pregunta":"resistencia_tierra","operador":">","valor":"25"},{"pregunta":"mejora_tierra_posible","operador":"=","valor":"true"}]},"mensaje":"Resistencia de tierra > 25 ohm","accion_o_tipo":"Mejorar sistema de tierra"},{"etiqueta":"ING-R010","codigo":"regla_tierra_sin_mejora","severidad":"requiere_especialista","efecto":"validacion_especializada","cuando":{"and":[{"pregunta":"resistencia_tierra","operador":">","valor":"25"},{"pregunta":"mejora_tierra_posible","operador":"=","valor":"false"}]},"mensaje":"Resistencia de tierra alta sin corrección definida","accion_o_tipo":"electrico"},{"etiqueta":"ING-R011","codigo":"regla_memoria_ausente","severidad":"bloqueante","efecto":"no_apto","cuando":{"pregunta":"memoria_calculo","operador":"=","valor":"false"},"mensaje":"Memoria de cálculo no aprobada","accion_o_tipo":"Completar Ingeniería"},{"etiqueta":"ING-R012","codigo":"regla_unifilar_ausente","severidad":"bloqueante","efecto":"no_apto","cuando":{"pregunta":"diagrama_unifilar","operador":"=","valor":"false"},"mensaje":"Diagrama unifilar no aprobado","accion_o_tipo":"Completar Ingeniería"},{"etiqueta":"ING-R013","codigo":"info_modelo_inversor","severidad":"informativa","efecto":"informativa","cuando":{"pregunta":"inversor_modelo","operador":"is_not_null"},"mensaje":"Registrar equipo final seleccionado","accion_o_tipo":null}]}]$json$;
  v_empresa integer;
  v_etapa jsonb;
  v_sec jsonb;
  v_preg jsonb;
  v_reg jsonb;
  v_op jsonb;
  v_cond jsonb;
  v_plantilla integer;
  v_sec_id integer;
  v_preg_id integer;
  v_orden_sec integer;
  v_orden_preg integer;
  v_orden_op integer;
  v_orden_reg integer;
  v_conds jsonb := '[]'::jsonb;
  v_res jsonb := '[]'::jsonb;
begin
  select id_empresa into v_empresa from empresas where nombre = p_empresa_nombre limit 1;
  if v_empresa is null then
    return jsonb_build_object('ok', false, 'motivo', 'empresa_no_encontrada', 'empresa', p_empresa_nombre);
  end if;

  <<play_loop>> for v_etapa in select * from jsonb_array_elements(v_payload) loop
    if exists (
      select 1 from viabilidad_plantillas
       where empresa_id = v_empresa and servicio_id is null
         and tipo_etapa = v_etapa->>'etapa' and estado = 'activa'
    ) then
      v_res := v_res || jsonb_build_array(jsonb_build_object(
        'etapa', v_etapa->>'etapa', 'estado', 'ya_existe'));
      continue play_loop;
    end if;

    perform set_config('zyra.rpc_plantilla', 'on', true);

    insert into viabilidad_plantillas(empresa_id, servicio_id, tipo_etapa, version, nombre, estado)
    values (
      v_empresa, null, v_etapa->>'etapa',
      coalesce((select max(version) from viabilidad_plantillas
                 where empresa_id = v_empresa and servicio_id is null
                   and tipo_etapa = v_etapa->>'etapa'), 0) + 1,
      v_etapa->>'nombre', 'activa')
    returning id_plantilla_viabilidad into v_plantilla;

    -- Archiva provisionales activas de la misma etapa (trazabilidad).
    update viabilidad_plantillas
       set estado = 'archivada'
     where empresa_id = v_empresa
       and tipo_etapa = v_etapa->>'etapa'
       and estado = 'activa'
       and id_plantilla_viabilidad <> v_plantilla;

    v_orden_sec := 0;
    for v_sec in select * from jsonb_array_elements(v_etapa->'secciones') loop
      v_orden_sec := v_orden_sec + 1;
      insert into viabilidad_secciones(plantilla_id, orden, codigo, titulo)
      values (v_plantilla, v_orden_sec, v_sec->>'codigo', v_sec->>'titulo')
      returning id_seccion_viabilidad into v_sec_id;

      v_orden_preg := 0;
      for v_preg in select * from jsonb_array_elements(v_sec->'preguntas') loop
        v_orden_preg := v_orden_preg + 1;
        insert into viabilidad_preguntas(
          seccion_id, orden, codigo, texto, ayuda, tipo_respuesta, obligatoria, activa,
          unidad, evidencia_tipo, evidencia_obligatoria, evidencia_obligatoria_condicion, evidencia_instruccion)
        values (
          v_sec_id, v_orden_preg, v_preg->>'codigo', v_preg->>'texto', v_preg->>'ayuda', v_preg->>'tipo',
          coalesce((v_preg->>'obligatoria')::boolean, false), true,
          v_preg->>'unidad', v_preg->>'evidencia_tipo',
          coalesce((v_preg->>'evidencia_obligatoria')::boolean, false),
          v_preg->'evidencia_obligatoria_condicion', v_preg->>'evidencia_instruccion')
        returning id_pregunta_viabilidad into v_preg_id;

        if v_preg ? 'opciones' then
          v_orden_op := 0;
          for v_op in select * from jsonb_array_elements(v_preg->'opciones') loop
            v_orden_op := v_orden_op + 1;
            insert into viabilidad_opciones(pregunta_id, orden, valor, etiqueta)
            values (v_preg_id, v_orden_op, v_op->>'valor', v_op->>'etiqueta');
          end loop;
        end if;

        if v_preg ? 'activacion' then
          for v_cond in select * from jsonb_array_elements(v_preg->'activacion') loop
            v_conds := v_conds || jsonb_build_array(jsonb_build_object(
              'destino', v_preg->>'codigo',
              'origen', v_cond->>'pregunta',
              'operador', v_cond->>'operador',
              'valor', v_cond->>'valor'));
          end loop;
        end if;
      end loop;
    end loop;

    -- Condiciones de activacion (segunda pasada: ya existen todas las preguntas).
    for v_cond in select * from jsonb_array_elements(v_conds) loop
      insert into viabilidad_condiciones(pregunta_id, pregunta_origen_id, operador, valor, accion)
      values (
        (select p2.id_pregunta_viabilidad
           from viabilidad_preguntas p2
           join viabilidad_secciones s2 on s2.id_seccion_viabilidad = p2.seccion_id
          where s2.plantilla_id = v_plantilla and p2.codigo = v_cond->>'destino'),
        (select p2.id_pregunta_viabilidad
           from viabilidad_preguntas p2
           join viabilidad_secciones s2 on s2.id_seccion_viabilidad = p2.seccion_id
          where s2.plantilla_id = v_plantilla and p2.codigo = v_cond->>'origen'),
        v_cond->>'operador', v_cond->>'valor', 'mostrar');
    end loop;
    v_conds := '[]'::jsonb;

    v_orden_reg := 0;
    for v_reg in select * from jsonb_array_elements(v_etapa->'reglas') loop
      v_orden_reg := v_orden_reg + 1;
      insert into viabilidad_reglas(
        plantilla_id, orden, etiqueta, codigo, severidad_funcional, efecto_funcional,
        cuando, mensaje, accion_o_tipo, validacion_tipo)
      values (
        v_plantilla, v_orden_reg, v_reg->>'etiqueta', v_reg->>'codigo',
        v_reg->>'severidad', v_reg->>'efecto', v_reg->'cuando', v_reg->>'mensaje',
        v_reg->>'accion_o_tipo',
        case when v_reg->>'efecto' = 'validacion_especializada' then v_reg->>'accion_o_tipo' else null end);
    end loop;

    v_res := v_res || jsonb_build_array(jsonb_build_object(
      'etapa', v_etapa->>'etapa', 'estado', 'sembrada', 'plantilla', v_plantilla));
  end loop play_loop;

  return jsonb_build_object('ok', true, 'empresa_id', v_empresa, 'resultado', v_res);
end;
$$;

revoke all on function public.sembrar_cuestionario_viabilidad_definitivo(text) from public, anon, authenticated;

-- Si la empresa ya existe (p.ej. reaplicando sobre una BD sembrada), publica ya.
do $$
begin
  if exists (select 1 from empresas where nombre = 'ESSE Solar') then
    perform public.sembrar_cuestionario_viabilidad_definitivo();
  end if;
end $$;

commit;
